   "oldText": "def transform(grid):
    # Draw 2s in every other cell between consecutive 7 marks.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == 7]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b, 2):
                out[r][c] = 2
    return out
",
   "newText": "def transform(grid):
    # Mark cells between adjacent same-color endpoint pairs, without filling
    # every gap in longer sequences: only the midpoint between consecutive 7s.
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c in range(1, len(row) - 1):
            if row[c - 1] == 7 and row[c + 1] == 7:
                out[r][c] = 2
    return out
